WITH filtered_customers AS (SELECT * FROM customers WHERE age BETWEEN 41 AND 49), CustomersStats AS (SELECT is_active, DATE_FORMAT(signup_date, 'yyyy-MM') signup_month, COUNT(CASE WHEN city = 'Tokyo' THEN 1 END) tokyo_count FROM filtered_customers GROUP BY is_active, DATE_FORMAT(signup_date, 'yyyy-MM')) SELECT is_active, signup_month, tokyo_count FROM CustomersStats WHERE tokyo_count >= 7 ORDER BY tokyo_count DESC
